<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){post_only();$id=(int)($_POST['id_prestamo']??0);try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT id_libro FROM prestamos WHERE id_prestamo=? AND estado_prestamo='Activo' FOR UPDATE");$s->execute([$id]);$p=$s->fetch();if(!$p)throw new RuntimeException('El préstamo ya se devolvió o no existe.');$pdo->prepare("UPDATE prestamos SET estado_prestamo='Devuelto' WHERE id_prestamo=?")->execute([$id]);$pdo->prepare("UPDATE libros SET estado='Disponible' WHERE id_libro=?")->execute([$p['id_libro']]);$pdo->commit();flash('success','Devolución registrada correctamente.');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash('error',$ex instanceof RuntimeException?$ex->getMessage():'No se pudo registrar la devolución.');}header('Location: devoluciones.php');exit;}
$rows=$pdo->query("SELECT p.*,u.nombre usuario,l.titulo libro,IF(p.fecha_devolucion<CURDATE(),'Atrasado','Activo') estado_vista FROM prestamos p JOIN usuarios u ON u.id_usuario=p.id_usuario JOIN libros l ON l.id_libro=p.id_libro WHERE p.estado_prestamo='Activo' ORDER BY p.fecha_devolucion")->fetchAll();page_start('Devoluciones','devoluciones.php');
?>
<div class="page-heading"><div><span class="eyebrow">CIRCULACIÓN</span><h1>Devoluciones</h1><p>Registra el retorno de los préstamos activos.</p></div></div><section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Préstamo</th><th>Fecha límite</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><?= e($p['usuario']); ?></td><td><?= e($p['libro']); ?></td><td><?= e($p['fecha_prestamo']); ?></td><td><?= e($p['fecha_devolucion']); ?></td><td><span class="badge rounded-pill text-bg-<?= $p['estado_vista']==='Atrasado'?'danger':'warning'; ?>"><?= e($p['estado_vista']); ?></span></td><td><form method="post" onsubmit="return confirm('¿Registrar devolución?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="id_prestamo" value="<?= (int)$p['id_prestamo']; ?>"><button class="btn btn-sm btn-success">Registrar devolución</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="text-center text-secondary py-4">No hay préstamos activos.</td></tr><?php endif; ?></tbody></table></div></section><?php page_end(); ?>
